INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var overgangen fra jæger-samler til landbrug en forbedring for det enkelte menneske — og hvad viser det arkæologiske skeletmateriale?","options":["Paradoksalt var det ikke en forbedring for individet: skeletanalyser viser at tidlige bønder var lavere, havde dårligere tænder, flere knoglesygdomme og mere anæmi end de jæger-samlere de afløste. Diæten blev snævrere og stresset fra hårdt landbrugsarbejde satte sig i knoglerne. Men landbruget var en demografisk succes på befolkningsniveau — flere mennesker per areal end jagtsamfund kunne bære. Jared Diamond kaldte overgangen provocerende 'den værste fejltagelse i menneskehedens historie' netop for at pointere at individuel velfærd og populationssucces kan divergere systematisk","Overgangen til landbrug var en entydig forbedring for individet: bedre mad, mere sikkerhed og længere liv — det arkæologiske skeletmateriale bekræfter konsekvent denne fremgang","Jæger-samlere var kronisk underernærede og sulte, og landbruget reddede dem fra konstant sult og tidlig død","Overgangen til landbrug kan ikke vurderes fra skeletmaterialet da knoglerne ikke bevares i dansk jord fra denne periode"],"correct":"Paradoksalt var det ikke en forbedring for individet: skeletanalyser viser at tidlige bønder var lavere, havde dårligere tænder, flere knoglesygdomme og mere anæmi end de jæger-samlere de afløste. Diæten blev snævrere og stresset fra hårdt landbrugsarbejde satte sig i knoglerne. Men landbruget var en demografisk succes på befolkningsniveau — flere mennesker per areal end jagtsamfund kunne bære. Jared Diamond kaldte overgangen provocerende 'den værste fejltagelse i menneskehedens historie' netop for at pointere at individuel velfærd og populationssucces kan divergere systematisk","accepted_answers":["Paradoksalt var det ikke en forbedring for individet: skeletanalyser viser at tidlige bønder var lavere, havde dårligere tænder, flere knoglesygdomme og mere anæmi end de jæger-samlere de afløste. Diæten blev snævrere og stresset fra hårdt landbrugsarbejde satte sig i knoglerne. Men landbruget var en demografisk succes på befolkningsniveau — flere mennesker per areal end jagtsamfund kunne bære. Jared Diamond kaldte overgangen provocerende 'den værste fejltagelse i menneskehedens historie' netop for at pointere at individuel velfærd og populationssucces kan divergere systematisk"],"review_text":"Mark Cohen og George Armelagos redigerede Paleopathology at the Origins of Agriculture (1984) — en systematisk gennemgang af skeletmaterialet fra overgangen til landbrug globalt. Resultaterne var konsistent: gennemsnitshøjden faldt, tandsygdomme steg dramatisk (sukker fra korn fodrer cariesbakterier), jernmangelsholdige betingelser blev hyppigere (enssidig korndiæt). Jæger-samlere havde adgang til et bredt spektrum af animalsk protein, nødder og bær. De nordiske Ertebøllekulturens skeletpopulationer (7000-3900 f.Kr.) var overraskende velnærede og robuste. Jared Diamonds provokation i Guns, Germs and Steel (1997) kapitel 10 er analytisk præcis: landbruget var en evolutionær succes (flere overlevende børn, højere befolkningstæthed) men en individuel velværdsnedgang. Distinktionen mellem individuel fitness og populationsfitness er afgørende for at forstå hvorfor maladaptive træk kan sprede sig."}$$::jsonb,
  'mc','short',$${"concepts":["jæger-samler","landbrug","skeletanalyse","Diamond","individuel vs populationsfitness","Ertebøllekulturen"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad viser moderne aDNA-forskning om overgangen fra jæger-samler til bonde i Sydskandinavien — og hvad ændrer det ved den klassiske kulturdiffusionstese?","options":["Gammel DNA fra fossile knogler (aDNA-studier fra 2015+, bl.a. Haak et al. og Mathieson et al.) viser massiv befolkningsudskiftning: anatolske bondepopulationer erstattede stort set de skandinaviske jæger-samlere frem for at de overtog en ny levevis. Det er ikke kulturdiffusion men demografisk erstatning med begrænset genetisk blanding. Dermed var 'overgangen til landbrug' i Danmark for mange menneskers vedkommende en invasions- og fortrængningsproces — ikke et fredeligt kulturelt valg","Ertebøllekulturens folk valgte bevidst at adoptere landbruget ved gradvis læringsudveksling med sydlige naboer — aDNA-forskning bekræfter fuldstændig den klassiske kulturdiffusionsmodel","aDNA-forskning har vist at der slet ingen genetisk forskel var mellem jæger-samlere og de første bønder i Sydskandinavien","aDNA-teknologi er for upålidelig til at sige noget meningsfuldt om forhistoriske befolkningsbevægelser i Skandinavien"],"correct":"Gammel DNA fra fossile knogler (aDNA-studier fra 2015+, bl.a. Haak et al. og Mathieson et al.) viser massiv befolkningsudskiftning: anatolske bondepopulationer erstattede stort set de skandinaviske jæger-samlere frem for at de overtog en ny levevis. Det er ikke kulturdiffusion men demografisk erstatning med begrænset genetisk blanding. Dermed var 'overgangen til landbrug' i Danmark for mange menneskers vedkommende en invasions- og fortrængningsproces — ikke et fredeligt kulturelt valg","accepted_answers":["Gammel DNA fra fossile knogler (aDNA-studier fra 2015+, bl.a. Haak et al. og Mathieson et al.) viser massiv befolkningsudskiftning: anatolske bondepopulationer erstattede stort set de skandinaviske jæger-samlere frem for at de overtog en ny levevis. Det er ikke kulturdiffusion men demografisk erstatning med begrænset genetisk blanding. Dermed var 'overgangen til landbrug' i Danmark for mange menneskers vedkommende en invasions- og fortrængningsproces — ikke et fredeligt kulturelt valg"],"review_text":"Wolfgang Haak et al. (Nature 2015) og Iain Mathieson et al. (Nature 2015) sekvenserede hundredvis af forhistoriske genomer og fandt at europæiske bondepopulationer var genetisk distinkte fra de mesolitiske jæger-samlere. I Sydskandinavien er der tegn på at Ertebøllekulturens folk og de første Tragtbægerkulturens bønder (ca. 3900 f.Kr.) udvekslede lidt genetisk materiale men at erstatningen var substantiel. David Reichs Who We Are and How We Got Here (2018) formidler implikationerne: store dele af forhistorisk Skandinavien var scene for demografiske udskiftninger vi ikke vidste om før genetikken. Det ændrer forhistorisk narrativ fundamentalt: 'de første danskere' der byggede megalitgrave var sandsynligvis genetisk fremmede for den mesolitiske befolkning de afløste. Yamnaya-pastoralisterne der ankom ca. 2800 f.Kr. udskiftede igen store dele af bondepopulationen. De fleste moderne danskere har rødder i alle tre migrationer — men ingen af dem er 'urindfødte danskere' i enkelt forstand."}$$::jsonb,
  'mc','short',$${"concepts":["aDNA","befolkningsudskiftning","Ertebøllekulturen","Tragtbægerkulturen","Haak","Reich"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var overgangen fra jæger-samler til landbrug reversibel — og hvad fortæller det om strukturel forandring i menneskelige samfund?","options":["Overgangen var ikke reversibel i praksis: når befolkningstætheden steg til at afhænge af landbrugets kalorieproduktion, var de habitater der muliggjorde jæger-samler-liv allerede degraderede eller overbefolkede. Sti-afhængighed (path dependency) betyder at tidlige valg indsnævrer fremtidige muligheder. Det var ikke et valg der kunne fortrydes — strukturelle tærskler er oftest ensrettede. Kun katastrofale befolkningssammenbrud (som Sortedøden) kunne delvist genåbne tidligere levemåder","Overgangen til landbrug var altid fuldt reversibel og mange forhistoriske samfund valgte bevidst at vende tilbage til jæger-samler-liv","Landbruget var så attraktivt at ingen befolkninger nogen sinde overvejede at vende tilbage til jæger-samler-strategier","Begrebet 'sti-afhængighed' er kun relevant for moderne industrielle samfund og ikke anvendeligt på forhistoriske befolkningstransitioner"],"correct":"Overgangen var ikke reversibel i praksis: når befolkningstætheden steg til at afhænge af landbrugets kalorieproduktion, var de habitater der muliggjorde jæger-samler-liv allerede degraderede eller overbefolkede. Sti-afhængighed (path dependency) betyder at tidlige valg indsnævrer fremtidige muligheder. Det var ikke et valg der kunne fortrydes — strukturelle tærskler er oftest ensrettede. Kun katastrofale befolkningssammenbrud (som Sortedøden) kunne delvist genåbne tidligere levemåder","accepted_answers":["Overgangen var ikke reversibel i praksis: når befolkningstætheden steg til at afhænge af landbrugets kalorieproduktion, var de habitater der muliggjorde jæger-samler-liv allerede degraderede eller overbefolkede. Sti-afhængighed (path dependency) betyder at tidlige valg indsnævrer fremtidige muligheder. Det var ikke et valg der kunne fortrydes — strukturelle tærskler er oftest ensrettede. Kun katastrofale befolkningssammenbrud (som Sortedøden) kunne delvist genåbne tidligere levemåder"],"review_text":"Peter Richersons og Robert Boyds Not by Genes Alone (2005) og James Scotts Against the Grain (2017) diskuterer landbrugets lock-in effekt. Scott argumenterer at de første statssamfund var demografisk ustabile — tidlige agrare bystater kollapsede gentagne gange og befolkninger vendte faktisk midlertidigt tilbage til semi-nomadiske strategier. Men ved større befolkningstætheder var dette umuligt: vildtbestandene og de urørte habitater var simpelthen ikke til stede. Douglass Norths path dependency-koncept (Institutions, Institutional Change and Economic Performance, 1990) er præcist: institutioner og levevis skaber positive feedback-loops der gør alternativerne progressivt dyrere. Matematisk kan man modellere tærsklen: under ca. 0,1 person per km² er jæger-samler-strategier bæredygtige; ved 10+ personer per km² kræver det landbrugets kalorietæthed. Danmark nåede i Bondestenalderen befolkningstætheder der passerede dette punkt. Irreversibiliteten er en empirisk observation, ikke en moraldom."}$$::jsonb,
  'mc','short',$${"concepts":["sti-afhængighed","landbrugstransition","irreversibilitet","befolkningstæthed","Scott","North"],"misconception_type":"false_equivalence","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad fortæller de lange perioder med koeksistens mellem Ertebøllekulturens jæger-samlere og Tragtbægerkulturens bønder i Sydskandinavien om forhistorisk kulturkontakt?","options":["Koeksistensperioden (ca. 3900-3500 f.Kr.) viser at forholdet ikke var simpel erstatning men kompleks kontakt: Ertebøllekulturens folk adopterede sporadisk keramik og husdyrhold fra bønderne mens de bevarede jæger-samler-kernen. Forskning viser genetisk minimal blanding men kulturelt udveksling. Det viser at forhistoriske folk var handlende agenter der selektivt adopterede elementer fra nabokulture frem for at blive passivt erstattet eller omdannet","Forholdet mellem Ertebøllekultur og Tragtbægerkultur var rent fjendtligt og der er arkæologisk dokumenteret systematisk krigsførelse uden kulturel udveksling","Ertebøllekulturen kollapsede øjeblikkeligt ved bondekulturens ankomst uden nogen koeksistensperiode","Ertebøllekulturens folk adopterede fuldt og frivilligt landbruget inden for en enkelt generation da de erkendte dets klare overlegenhed"],"correct":"Koeksistensperioden (ca. 3900-3500 f.Kr.) viser at forholdet ikke var simpel erstatning men kompleks kontakt: Ertebøllekulturens folk adopterede sporadisk keramik og husdyrhold fra bønderne mens de bevarede jæger-samler-kernen. Forskning viser genetisk minimal blanding men kulturelt udveksling. Det viser at forhistoriske folk var handlende agenter der selektivt adopterede elementer fra nabokulture frem for at blive passivt erstattet eller omdannet","accepted_answers":["Koeksistensperioden (ca. 3900-3500 f.Kr.) viser at forholdet ikke var simpel erstatning men kompleks kontakt: Ertebøllekulturens folk adopterede sporadisk keramik og husdyrhold fra bønderne mens de bevarede jæger-samler-kernen. Forskning viser genetisk minimal blanding men kulturelt udveksling. Det viser at forhistoriske folk var handlende agenter der selektivt adopterede elementer fra nabokulture frem for at blive passivt erstattet eller omdannet"],"review_text":"Ertebøllekulturens (ca. 5400-3900 f.Kr.) relation til de første bønder er et centralt problem i dansk forhistorie. Lotte Bredholts Kristiansen og Peter Rowleys-Conwy har vist at Ertebøllekulturens folk faktisk producerede keramik og holdt husdyr i et begrænset omfang i overgangsperioden — det er ikke passiv jæger-samler-konservatisme. Arkæologiske fund fra Meilgaard og Norsminde Fjord viser at Ertebølle-bopladser eksisterede side om side med bondebopladser i en periode. Den genetiske forskning (Skoglund et al. 2012; Haak et al. 2015) viser at den genetiske blanding var begrænset — hvilket taler for at de to grupper levede relativt adskilte parallelliv snarere end at assimilere sig. Det interessante spørgsmål for aktørteoretikerne (James C. Scott, David Graeber og David Wengrws The Dawn of Everything, 2021): valgte Ertebøllekulturens folk aktivt en 'mixed strategy' der kombinerede begge levemåder? Graebers og Wengrws tese er at forhistoriske folk havde større politisk og kulturel fleksibilitet end vi tillægger dem — de var ikke determinerede af deres subsistensstrategi."}$$::jsonb,
  'mc','short',$${"concepts":["Ertebøllekulturen","Tragtbægerkultur","koeksistens","kulturkontakt","Graeber","aktørteori"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

-- ─── BAND 5 · ARKÆOLOGISK METODE & KILDEKRITIK (4 questions) ─────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"P.V. Glob fortolkede moseligene som ofre til frugtbarhedsgudinder — hvor stærk er denne fortolkning, og hvad er de metodologiske begrænsninger?","options":["Globs fortolkning er inspirerende men metodologisk svag: den er baseret på analogi med germanske fertilitetskultbeskrivelser hos Tacitus (skrevet 500+ år efter Tollandmanden) og sammenligning med andre mosefund. Den arkæologiske evidens (snore om halsen, placering i mose, tidspunkt på Ertebølle-tid) er kompatibel med Globs tese men bekræfter den ikke. Alternativer er metodologisk lige gyldige: henrettelse af forbrydere, krigsofre, udstødelse af samfundsskadelige individer. Fraværet af skriftlige samtidige kilder gør enhver specifik rituel fortolkning til hypotese, ikke kendsgerning","Globs fortolkning er videnskabeligt bekræftet og der er bred konsensus om at moseligene var frugtbarhedsoffer — fortolkningsalternativer er marginale","Moseligene er bevist henrettede forbrydere og Globs religiøse fortolkning er fuldstændigt afvist af moderne forskning","Moseligenes rituelle fortolkning er arkæologisk umulig at adressere og alle fortolkningsforsøg er metodologisk illegitime spekulation"],"correct":"Globs fortolkning er inspirerende men metodologisk svag: den er baseret på analogi med germanske fertilitetskultbeskrivelser hos Tacitus (skrevet 500+ år efter Tollandmanden) og sammenligning med andre mosefund. Den arkæologiske evidens (snore om halsen, placering i mose, tidspunkt på Ertebølle-tid) er kompatibel med Globs tese men bekræfter den ikke. Alternativer er metodologisk lige gyldige: henrettelse af forbrydere, krigsofre, udstødelse af samfundsskadelige individer. Fraværet af skriftlige samtidige kilder gør enhver specifik rituel fortolkning til hypotese, ikke kendsgerning","accepted_answers":["Globs fortolkning er inspirerende men metodologisk svag: den er baseret på analogi med germanske fertilitetskultbeskrivelser hos Tacitus (skrevet 500+ år efter Tollandmanden) og sammenligning med andre mosefund. Den arkæologiske evidens (snore om halsen, placering i mose, tidspunkt på Ertebølle-tid) er kompatibel med Globs tese men bekræfter den ikke. Alternativer er metodologisk lige gyldige: henrettelse af forbrydere, krigsofre, udstødelse af samfundsskadelige individer. Fraværet af skriftlige samtidige kilder gør enhver specifik rituel fortolkning til hypotese, ikke kendsgerning"],"review_text":"P.V. Glob (Mosefolket, 1965) er det klassiske arbejde og en beundringsværdig formidling. Hans fortolkningstese: Tollandmanden og andre moselig var ofret til Nerthus (germansk frugtbarhedsgudinde) i forbindelse med forårsfrugtbarhedsritualer — Tacitus' Germania (98 e.Kr.) beskriver netop sådanne ritealer. Det metodologiske problem er kronologisk og analogisk: Tacitus beskriver germanske skikke næsten 500 år efter de fleste af de kendte moselig. Miranda Green (Dying for the Gods, 2001) og Karin Sanders (Bodies of the Bogs and the Archaeological Imagination, 2009) har kritiseret den ukritiske overføring. Sanders viser at europæisk fascination for moselig delvist er romantisk projektion — vi tillægger dem den overnaturlige aura vi søger. Stifford Crisps studie (2007) af de 1.000+ registrerede europæiske mosefund viser at mosene tjente multiple formål: deponering af offergenstande, afskaffelse af udtjente redskaber, og sandsynligvis også af socialt stigmatiserede individer. Ensartet fortolkning er uholdbar."}$$::jsonb,
  'mc','short',$${"concepts":["moseleg","Glob","Tacitus","kildekritik","Tollandmanden","fortolkningsgrænser"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad kan Trundholmvognens solvogn (ca. 1400 f.Kr.) fortælle os om bronzealdersreligion — og hvad kan den ikke fortælle os?","options":["Vi kan fastslå det materielle: en bronzehest trækker en gylden og sort solskive på hjul — det er et spektakulært håndværk der kræver avancerede støbeteknikker. Vi kan sandsynliggøre solreligion baseret på komparative fund og billedfremstillinger fra nordisk bronzealder. Men vi kan ikke vide noget om ritualets præcise form, hvem der ejede vognens, om den blev brugt dagligt eller ved specifikke anledninger, eller hvad de troende faktisk mente med den. Uden skriftlige kilder er specifikke rituelle tolkninger hypoteser, ikke videnskabelige fakta","Trundholmvognen er fuldt fortolket og vi ved præcis at den repræsenterede solgudens daglige rejse over himlen ifølge bronzealdersfolkets præcise forestillingsverden","Trundholmvognen er for enkelt et fund til at vi kan drage nogen arkæologiske slutninger om bronzealdersreligion fra det","Bronzealderens religion er fuldstændig dokumenteret via Trundholmvognen og andre billedfremstillinger der giver et komplet billede"],"correct":"Vi kan fastslå det materielle: en bronzehest trækker en gylden og sort solskive på hjul — det er et spektakulært håndværk der kræver avancerede støbeteknikker. Vi kan sandsynliggøre solreligion baseret på komparative fund og billedfremstillinger fra nordisk bronzealder. Men vi kan ikke vide noget om ritualets præcise form, hvem der ejede vognens, om den blev brugt dagligt eller ved specifikke anledninger, eller hvad de troende faktisk mente med den. Uden skriftlige kilder er specifikke rituelle tolkninger hypoteser, ikke videnskabelige fakta","accepted_answers":["Vi kan fastslå det materielle: en bronzehest trækker en gylden og sort solskive på hjul — det er et spektakulært håndværk der kræver avancerede støbeteknikker. Vi kan sandsynliggøre solreligion baseret på komparative fund og billedfremstillinger fra nordisk bronzealder. Men vi kan ikke vide noget om ritualets præcise form, hvem der ejede vognens, om den blev brugt dagligt eller ved specifikke anledninger, eller hvad de troende faktisk mente med den. Uden skriftlige kilder er specifikke rituelle tolkninger hypoteser, ikke videnskabelige fakta"],"review_text":"Trundholmvognen (fundet 1902, dateret ca. 1400 f.Kr.) er et af nordeuropæisk bronzealders mest imponerende fund: en bronzehest trækker en bronzeskive overtrukket med guldfolie på den ene side og sort på den anden — sandsynligvis symboliserende sol og nat. Karin Margarita Frei og kollegers isotopanalyser (2015) viste at guldfolien kom fra Irland eller Spanien — dokumentation for vidtrækkende handelsnetværk. Flemming Kaul (Nationalmuseets bronzealderspecialist) fortolker skiven og relaterede billeder fra barbierknive og rageknive som del af et sammenhængende solmytologisk narrativ om solens rejse over himlen dag og nat og under havet. Det er den stærkeste tilgængelige fortolkning. Men som Kauls eget metodepapir (Ships on Bronzes, 1998) erkender: uden tekster er ikonografisk analyse analogibaseret. Vi identificerer mønstre og sammenligner med eksplicitte mytologiske forestillinger fra andre kulturer (egyptisk, vedisk) — men projektion er en reel metodisk risiko. Historikerens grundregel: vær præcis om hvad kilden viser og hvad der er konstrueret fortolkning."}$$::jsonb,
  'mc','short',$${"concepts":["Trundholmvognen","solreligion","ikonografisk analyse","kildekritik","Kaul","bronzealder"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det marine reservoireffekt-problemet i kulstof-14-datering af forhistorisk Danmark — og hvad fortæller det om videnskabelig usikkerhed?","options":["Kystboende forhistoriske danskere (fx Ertebøllekulturen) spiste store mængder fisk og skaldyr. Havets kulstofreservoir er ældre end atmosfærens fordi havvand optager og cirkulerer CO2 langsomt. Kulstof-14-datering af folk med marin diæt giver datoer der tilsyneladende er 400-800 år ældre end de faktisk er. Korrektioner er mulige men introducerer yderligere usikkerhed. Det viser at videnskabelige metoder altid har systematiske fejlkilder der kræver metaanalyse og korrektionsmodeller — og at datoer er estimater med fejlmarginer, ikke fakta","Kulstof-14-datering er en perfekt præcis metode uden kendte fejlkilder som marine reservoireffekter eller kalibreringsproblemer","Kulstof-14-datering er upålidelig i alle forhistoriske sammenhænge og kan ikke bruges til at datere noget fra forhistorisk Danmark","Marindiæt-problemet gælder kun for havboende pattedyr og påvirker ikke datering af menneskeknogler fra forhistorisk Danmark"],"correct":"Kystboende forhistoriske danskere (fx Ertebøllekulturen) spiste store mængder fisk og skaldyr. Havets kulstofreservoir er ældre end atmosfærens fordi havvand optager og cirkulerer CO2 langsomt. Kulstof-14-datering af folk med marin diæt giver datoer der tilsyneladende er 400-800 år ældre end de faktisk er. Korrektioner er mulige men introducerer yderligere usikkerhed. Det viser at videnskabelige metoder altid har systematiske fejlkilder der kræver metaanalyse og korrektionsmodeller — og at datoer er estimater med fejlmarginer, ikke fakta","accepted_answers":["Kystboende forhistoriske danskere (fx Ertebøllekulturen) spiste store mængder fisk og skaldyr. Havets kulstofreservoir er ældre end atmosfærens fordi havvand optager og cirkulerer CO2 langsomt. Kulstof-14-datering af folk med marin diæt giver datoer der tilsyneladende er 400-800 år ældre end de faktisk er. Korrektioner er mulige men introducerer yderligere usikkerhed. Det viser at videnskabelige metoder altid har systematiske fejlkilder der kræver metaanalyse og korrektionsmodeller — og at datoer er estimater med fakta"],"review_text":"Reservoireffekten er et af de vigtigste metodiske problemer i skandinavisk forhistorisk arkæologi. Peter Rowley-Conwy og Niels Noe-Nygaard har arbejdet med problemet i dansk kontekst. Ertebøllekulturens folk ved Danmarks kyster var primært marinbaserede — isotopanalyser af skelet-strontium viser at 50-80% af deres kaloriindtag kom fra havet. Det betyder at direkte C14-datering af deres knogler kan give datoer der ser ud til at være 400-800 år ældre end de faktisk er uden korrektion. IntCal-kalibreringskurverne (opdateret 2020) inkluderer marine reservoir-korrektionsfaktorer (MRF), men disse kræver kendskab til den præcise andel marin diæt — et cirkulært problem da vi bruger isotopdata til at estimere diæt og diætestimater til at korrigere dateringen. Den bredere metodologiske pointe: alle naturvidenskabelige målinger har systematiske og tilfældige fejl. At præsentere C14-datoer som præcise årstal uden fejlmarginer er metodisk ukorrekt. Arkæologisk kronologi er altid probabilistisk — den gode forsker kommunikerer usikkerhed eksplicit."}$$::jsonb,
  'mc','short',$${"concepts":["kulstof-14","marin reservoireffekt","Ertebøllekulturen","videnskabelig usikkerhed","kalibrering","metodekritik"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det systematiske bevaringsbias i forhistorisk arkæologi — og hvilke samfundsgrupper og aktiviteter bliver usynlige som konsekvens?","options":["Materialer der bevares: sten, brændt ler, bronze, jern, knogler i specifikke jordbundsforhold, og undtagelsesvis organisk materiale i moser og permafrost. Materialer der forsvinder: træ, tekstil, skind, flettet materiale, mad, alle verbale ytringer og videnssystemer. Aktiviteter der forsvinder: kvindernes arbejde (tekstil, madlavning, børnepasning), ritualer uden varige genstande, hverdagsliv for de fleste mennesker. Resultatet: den arkæologiske forhistorie overrepræsenterer mandlige elitegenstande (våben, smykker, store gravhøje) og underrepræsenterer de flestes liv systematisk","Arkæologisk bevaringsbias er minimal da moderne udgravningsteknikker kan rekonstruere al menneskelig aktivitet fra forhistorisk tid","Bevaringsbias påvirker kun genstande og ikke arkæologernes evne til at rekonstruere samfundsstrukturer og menneskelige aktiviteter","Kvinders arbejde og aktiviteter er lige så godt dokumenteret i det arkæologiske materiale som mandlige krigeres fordi køn ikke påvirker hvad der bevares"],"correct":"Materialer der bevares: sten, brændt ler, bronze, jern, knogler i specifikke jordbundsforhold, og undtagelsesvis organisk materiale i moser og permafrost. Materialer der forsvinder: træ, tekstil, skind, flettet materiale, mad, alle verbale ytringer og videnssystemer. Aktiviteter der forsvinder: kvindernes arbejde (tekstil, madlavning, børnepasning), ritualer uden varige genstande, hverdagsliv for de fleste mennesker. Resultatet: den arkæologiske forhistorie overrepræsenterer mandlige elitegenstande (våben, smykker, store gravhøje) og underrepræsenterer de flestes liv systematisk","accepted_answers":["Materialer der bevares: sten, brændt ler, bronze, jern, knogler i specifikke jordbundsforhold, og undtagelsesvis organisk materiale i moser og permafrost. Materialer der forsvinder: træ, tekstil, skind, flettet materiale, mad, alle verbale ytringer og videnssystemer. Aktiviteter der forsvinder: kvindernes arbejde (tekstil, madlavning, børnepasning), ritualer uden varige genstande, hverdagsliv for de fleste mennesker. Resultatet: den arkæologiske forhistorie overrepræsenterer mandlige elitegenstande (våben, smykker, store gravhøje) og underrepræsenterer de flestes liv systematisk"],"review_text":"Ian Morris (Archaeology as Cultural History, 2000) og Lynn Meskell (Object Worlds in Ancient Egypt, 2004) har systematiseret spørgsmålet om arkæologisk repræsentativitet. Etnobotanikken har delvist løst plantematerialproblemet via frøanalyse fra brændte lag og fossile pollen. Men tekstilernes fravær er fundamentalt: tekstil var en af de vigtigste teknologier og erhvervsaktiviteter — spindewhorl-fund (lerklumper brugt i spinding) er en af de få spor. Joan Gelbs tekstilanalyser og Elisabeth Barbers Women's Work: The First 20,000 Years (1994) viser at kvinder sandsynligvis dominerede tekstilproduktionen i forhistorien — men tekstilerne selv er borte. Ligeledes: hverdagskeramik (køkkenredskaber) overlever som skår, men madlavningsprocessen selv forsvinder. Den metodologiske implikation for historiske narrativer er alvorlig: når vi fortæller om forhistoriens 'storhed' via imponerende fund som Trundholmvognen og Egtvedpigen, fortæller vi om en lille minoritet hvis materielle kultur tilfældigvis overlever. Det er ikke forhistorien — det er forhistoriens filter."}$$::jsonb,
  'mc','short',$${"concepts":["bevaringsbias","køn og arkæologi","tekstil","Barber","arkæologisk repræsentativitet","kvinders arbejde"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

-- ─── BAND 5 · NEOLITISK REVOLUTION (4 questions) ─────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Gordon Childes begreb 'den neolitiske revolution' — er det analytisk præcist, og hvad viser det om historieskrivningens brug af dramaturgi?","options":["Begrebet er analytisk misvisende men pædagogisk nyttigt: 'revolution' antyder hurtighed og brud men overgangen til landbrug i Danmark tog 500-1000 år og var gradvis med lange perioder af koeksistens. Childe lånte marxistisk revolutionsbegreb og overførte det på en årtusindelang transformation. Det er et eksempel på at historieskrivning bruger dramaturgiske metaforer der simplificerer kausal kompleksitet — 'revolution' mobiliserer opmærksomhed men kan forvrænge forståelsen af processer der er strukturelt betingede og langsomt udviklende","Gordon Childes begreb 'den neolitiske revolution' er fuldt præcist og beskriver korrekt en hurtig og entydig overgang der skete inden for en enkelt menneskealder","Begrebet er udelukkende negativt og bør droppes totalt fra arkæologisk og historisk terminologi uden erstatning","Overgangen til landbrug var faktisk hurtigere end Childe forestillede sig og begrebet 'revolution' undervurderer ændringens dramatiske tempo"],"correct":"Begrebet er analytisk misvisende men pædagogisk nyttigt: 'revolution' antyder hurtighed og brud men overgangen til landbrug i Danmark tog 500-1000 år og var gradvis med lange perioder af koeksistens. Childe lånte marxistisk revolutionsbegreb og overførte det på en årtusindelang transformation. Det er et eksempel på at historieskrivning bruger dramaturgiske metaforer der simplificerer kausal kompleksitet — 'revolution' mobiliserer opmærksomhed men kan forvrænge forståelsen af processer der er strukturelt betingede og langsomt udviklende","accepted_answers":["Begrebet er analytisk misvisende men pædagogisk nyttigt: 'revolution' antyder hurtighed og brud men overgangen til landbrug i Danmark tog 500-1000 år og var gradvis med lange perioder af koeksistens. Childe lånte marxistisk revolutionsbegreb og overførte det på en årtusindelang transformation. Det er et eksempel på at historieskrivning bruger dramaturgiske metaforer der simplificerer kausal kompleksitet — 'revolution' mobiliserer opmærksomhed men kan forvrænge forståelsen af processer der er strukturelt betingede og langsomt udviklende"],"review_text":"Gordon Childe introducerede begrebet i Man Makes Himself (1936) og What Happened in History (1942) — begge bøger skrevet i en marxistisk intellektuel tradition der favoriserede revolutionære brud som historiske motorer. Childe vidste at overgangen ikke var øjeblikkelig men brugte 'revolution' som analytisk kontrast til evolutionær gradualisme. Brian Fagan (People of the Earth, 2007) og Kent Flannery har kritiseret terminologien: processen i Mellemøsten tog 3.000 år fra de første kultiverede planter til fuldt agrare samfund. I Nordeuropa endnu langsommere. Timothy Earle og Ian Kristiansen (Political Economies in Early State Formation, 2010) viser at den neolitiske transition var ikke én ting men en serie af regionale processer med varierende tempo. Det historiografiske problem er generelt: ord som 'revolution', 'kollaps', og 'krise' er dramaturgiske signaler der aktiverer forventninger om hurtighed og brud. De er ikke neutrale beskrivelser. Det metodologisk sofistikerede er at bruge dem mens man eksplicit adresserer hvad de simplificerer."}$$::jsonb,
  'mc','short',$${"concepts":["neolitisk revolution","Childe","historiografisk terminologi","gradualisme","dramaturgiske metaforer","begrebskritik"],"misconception_type":"temporal_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad forklarer at landbrug opstod uafhængigt på flere kontinenter — og hvad fortæller det om forholdet mellem struktur og aktørhandlen i historisk forandring?","options":["Multiple uafhængige domesticeringscentre (Frugtbar Halvmåne ca. 10000 f.Kr., Kina ca. 8000 f.Kr., Mexico ca. 5000 f.Kr., New Guinea ca. 7000 f.Kr.) viser at landbruget ikke var en singulær opfindelses-genialitet men en konvergent respons på lignende betingelser: Holocæns klimatiske opvarmning, befolkningspres, tilgængelighed af domesticerbare planter og dyr. Det taler for strukturel determinisme snarere end heroisk aktørhandlen — strukturelle betingelser skabte et vindue for transformation og menneskelige samfund der befandt sig i disse betingelser udviklede lignende løsninger. Det udelukker dog ikke at specifikke aktører spillede roller i de lokale processer","Landbrug opstod kun ét sted (Mellemøsten) og spredte sig derfra til resten af verden — begrebet om multiple uafhængige domesticeringscentre er en moderne myte","Multiple domesticeringscentre viser at enkeltindividernes geniale opfindelsesevne er den afgørende faktor i historisk forandring","Klimatiske betingelser er irrelevante for forklaring af landbrugets oprindelse da menneskelig kultur er fuldt autonomt fra naturbetingede faktorer"],"correct":"Multiple uafhængige domesticeringscentre (Frugtbar Halvmåne ca. 10000 f.Kr., Kina ca. 8000 f.Kr., Mexico ca. 5000 f.Kr., New Guinea ca. 7000 f.Kr.) viser at landbruget ikke var en singulær opfindelses-genialitet men en konvergent respons på lignende betingelser: Holocæns klimatiske opvarmning, befolkningspres, tilgængelighed af domesticerbare planter og dyr. Det taler for strukturel determinisme snarere end heroisk aktørhandlen — strukturelle betingelser skabte et vindue for transformation og menneskelige samfund der befandt sig i disse betingelser udviklede lignende løsninger. Det udelukker dog ikke at specifikke aktører spillede roller i de lokale processer","accepted_answers":["Multiple uafhængige domesticeringscentre (Frugtbar Halvmåne ca. 10000 f.Kr., Kina ca. 8000 f.Kr., Mexico ca. 5000 f.Kr., New Guinea ca. 7000 f.Kr.) viser at landbruget ikke var en singulær opfindelses-genialitet men en konvergent respons på lignende betingelser: Holocæns klimatiske opvarmning, befolkningspres, tilgængelighed af domesticerbare planter og dyr. Det taler for strukturel determinisme snarere end heroisk aktørhandlen — strukturelle betingelser skabte et vindue for transformation og menneskelige samfund der befandt sig i disse betingelser udviklede lignende løsninger. Det udelukker dog ikke at specifikke aktører spillede roller i de lokale processer"],"review_text":"Dolores Pipernos og Irene Holsts botaniske forskning har identificeret og dateret de ældste kendte domesticerede planter i Mexico og Sydamerika. Jack Harlan kortlagde i Crops and Man (1975) de primære domesticeringscentre. Jared Diamonds Guns, Germs and Steel (1997) systematiserede argumentet for at geografisk struktur (tilgængelighed af domesticerbare arter, aks-orientering der muliggør spredning på samme breddegrader) forklarer HVORFOR nogle regioner fik landbrug tidligst. Det er strukturalistisk argumentarion: individuelle aktørers kreativitet er sekundær i forhold til strukturelle muligheder. Marshall Sahlins (Stone Age Economics, 1972) udfordrer fra modsat side: han dokumenterer at nutidens resterende jæger-samlere faktisk arbejder færre timer om dagen end bønder og har rigere proteindiet — han kalder dem 'the original affluent society'. Valget om at adoptere landbrug var dermed ikke åbenbart rationelt for individet. Konsekvensen: stor historisk transformation behøver ikke forklaringer i form af geniale individuelle opdagelser men i strukturelle betingelser der gør visse udviklinger sandsynlige."}$$::jsonb,
  'mc','short',$${"concepts":["multiple domesticeringscentre","strukturel determinisme","aktørhandlen","Sahlins","Diamond","Holocæn"],"misconception_type":"causal_inversion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var klimaets rolle i den neolitiske transition i Nordeuropa — og hvad er risikoen ved klimadeterministiske forklaringer?","options":["Holocæns opvarmning (fra ca. 9600 f.Kr.) skabte et varmere og mere stabilt klima der muliggjorde nordeuropæisk landbrug: stejl klimaforbedring åbnede mulighedsvinduer for kornavl. Men klimadeterminisme er en analytisk risiko: klimaet skaber betingelser, ikke determinerer udfaldet. Afrika og Australien fik lignende Holocæn opvarmning men udviklede ikke selvstændigt intensive landbrug. Strukturelle faktorer (tilgængelighed af domesticerbare arter, befolkningsdynamik, sociale incentiver) medierer klimaets effekt. Klimaet er en nødvendig men ikke tilstrækkelig betingelse","Klimaforandringer forklarer fuldt og tilstrækkeligt overgangen til landbrug i Danmark — intet andet var nødvendigt end den rette temperatur","Klimaet spillede ingen rolle i den neolitiske transition — kulturelle og sociale faktorer var de eneste relevante forklaringsvariabler","Klimaforskning er for usikker til at give meningsfulde bidrag til forståelsen af den neolitiske transition i Nordeuropa"],"correct":"Holocæns opvarmning (fra ca. 9600 f.Kr.) skabte et varmere og mere stabilt klima der muliggjorde nordeuropæisk landbrug: stejl klimaforbedring åbnede mulighedsvinduer for kornavl. Men klimadeterminisme er en analytisk risiko: klimaet skaber betingelser, ikke determinerer udfaldet. Afrika og Australien fik lignende Holocæn opvarmning men udviklede ikke selvstændigt intensive landbrug. Strukturelle faktorer (tilgængelighed af domesticerbare arter, befolkningsdynamik, sociale incentiver) medierer klimaets effekt. Klimaet er en nødvendig men ikke tilstrækkelig betingelse","accepted_answers":["Holocæns opvarmning (fra ca. 9600 f.Kr.) skabte et varmere og mere stabilt klima der muliggjorde nordeuropæisk landbrug: stejl klimaforbedring åbnede mulighedsvinduer for kornavl. Men klimadeterminisme er en analytisk risiko: klimaet skaber betingelser, ikke determinerer udfaldet. Afrika og Australien fik lignende Holocæn opvarmning men udviklede ikke selvstændigt intensive landbrug. Strukturelle faktorer (tilgængelighed af domesticerbare arter, befolkningsdynamik, sociale incentiver) medierer klimaets effekt. Klimaet er en nødvendig men ikke tilstrækkelig betingelse"],"review_text":"Brian Faure og Gifford Miller (Annual Review of Earth and Planetary Sciences, 1997) og H.J.B. Birks palynologiske forskning dokumenterer Holocæns klimatiske stabilitet og opvarmning i Nordeuropa i detaljer fra pollenanalyse. De atlantiske og subboreal-perioder (ca. 7000-2500 f.Kr.) var varmere end i dag i Nordeuropa — Danmark kunne dyrke afgrøder som nu er marginale. Climatic Determinism-kritikken er formuleret af William McNeill (The Shape of European History, 1974) og Andrew Sherratts (Economy and Society in Prehistoric Europe, 1997) komparative studier: klimatisk determinisme sletter menneskelig kreativitet og social strukturering. Peter Bellwoods First Farmers (2005) viser at Europa er langt mere præget af migrerende bondepopulationer end af lokal adoption — klimaet skabte betingelsen for migration men migrationen var demografisk drevet. Den metodologiske vigtige distinktion: monokausal forklaring (klimaet alene) vs. multifaktoriel analyse (klimaet som en faktor der interagerer med biologi, demografi og social organisation)."}$$::jsonb,
  'mc','short',$${"concepts":["Holocæn","klimadeterminisme","neolitisk transition","nødvendig vs tilstrækkelig betingelse","Bellwood","palynologi"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var megalitternes sociale funktion i neolitisk Danmark — og hvad viser historiografiens skift i fortolkningerne?","options":["Fortolkningerne har skiftet markant: tidlig forskning betonede megalitter som gravminder (individuel eller dynastisk funktion). Nyere forskning (Hodder, Tilley, Fleming) betvivler den simple gravsmonument-tese: mange megalitter indeholdt skiftende og blandede knogler fra mange individer over lange perioder — de fungerede sandsynligvis som fælles territoriale markører, rituelt centrum for lokalsamfund og måske som 'arkiver' for forfædrenes legitimerende nærvær. Skiftet illustrerer at arkæologisk fortolkning er teoribundet — den sociale teori man anlægger afgør hvad man ser","Megalitternes funktion er fuldt klarlagt som individuelle gravminder for stammehøvdinge og der er bred konsensus i forskningen","Megalitter havde ingen social funktion men var rent praktiske konstruktioner til opbevaring og har intet med religion eller social organisation at gøre","Megalitternes funktion er principielt umulig at besvare og ethvert forsøg er metodologisk illegitim spekulation uden evidensgrundlag"],"correct":"Fortolkningerne har skiftet markant: tidlig forskning betonede megalitter som gravminder (individuel eller dynastisk funktion). Nyere forskning (Hodder, Tilley, Fleming) betvivler den simple gravsmonument-tese: mange megalitter indeholdt skiftende og blandede knogler fra mange individer over lange perioder — de fungerede sandsynligvis som fælles territoriale markører, rituelt centrum for lokalsamfund og måske som 'arkiver' for forfædrenes legitimerende nærvær. Skiftet illustrerer at arkæologisk fortolkning er teoribundet — den sociale teori man anlægger afgør hvad man ser","accepted_answers":["Fortolkningerne har skiftet markant: tidlig forskning betonede megalitter som gravminder (individuel eller dynastisk funktion). Nyere forskning (Hodder, Tilley, Fleming) betvivler den simple gravsmonument-tese: mange megalitter indeholdt skiftende og blandede knogler fra mange individer over lange perioder — de fungerede sandsynligvis som fælles territoriale markører, rituelt centrum for lokalsamfund og måske som 'arkiver' for forfædrenes legitimerende nærvær. Skiftet illustrerer at arkæologisk fortolkning er teoribundet — den sociale teori man anlægger afgør hvad man ser"],"review_text":"Ian Hodder (The Domestication of Europe, 1990) og Christopher Tilley (A Phenomenology of Landscape, 1994) repræsenterer det post-processuelle paradigmeskift i arkæologi: i stedet for funktionalistisk analyse (hvad tjente monumentet til?) spørger de om social og symbolsk mening i kontekst. Andrew Flemings kritik af overdreven symbolisme (Do We Need Cognitive Maps?, 1999) viser at pendlen kan svinge for langt. Danske megalitgrave (jættestuer, dysser) har typisk skiftende indhold: knogler er fjernet og genindsat, blandet med skår og dyreben over 500-1000 år. Det er svært at forklare funktionelt som simpelt gravminde. Niels Andersen og Lisbeth Pedersens udgravninger i Sarup (neolitisk indhegnet anlæg på Fyn) viser at megalitter indgik i større ritualiserede landskaber med festpladser og offersteder. Den metodologiske pointe: skiftende fortolkninger af det samme materiale afspejler ikke at arkæologerne er inkompetente men at fortolkning altid er teoristyret. At se dette er videnskabelig modenhed."}$$::jsonb,
  'mc','short',$${"concepts":["megalitter","Hodder","post-processuel arkæologi","teoribundet fortolkning","jættestuer","Tilley"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

-- ─── BAND 5 · BRONZEALDER, JERNALDER OG SOCIAL KOMPLEKSITET (4 questions) ────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad fortæller bronzealderskulturens handelsnetværk os om politisk organisation — og er det muligt at udlede statsformation fra materielt fund?","options":["Bronzens tilstedeværelse i Danmark kræver import (tin fra Cornwall og Centraleuropa, kobber fra Alperne og Sardinien) over tusindvis af kilometer. Kontrol over adgangen til bronze giver social magt — koncentration af bronzegenstande i visse grave indikerer en fremvoksende elite. Men om dette var arvet elite (proto-aristokrati), opnået status (handelshøvdinge) eller rituelt baseret autoritet (religiøse specialister) kan vi ikke afgøre fra materialet alene. Statsformation kræver specifikt administrative institutioner vi ikke kan se i arkæologiske fund","Bronzealderskulturens handelsnetværk dokumenterer fuld statsformation med skrevne love, skatteindkrævning og professionelle hære","Koncentrationen af bronzegenstande i visse grave viser udelukkende tilfældig bevaring og siger intet meningsfuldt om social differentiering","Bronzealderens handelsmønstre er fuldt forklarede som ligeværdig gavudveksling uden eliteformation eller social hierarkisering"],"correct":"Bronzens tilstedeværelse i Danmark kræver import (tin fra Cornwall og Centraleuropa, kobber fra Alperne og Sardinien) over tusindvis af kilometer. Kontrol over adgangen til bronze giver social magt — koncentration af bronzegenstande i visse grave indikerer en fremvoksende elite. Men om dette var arvet elite (proto-aristokrati), opnået status (handelshøvdinge) eller rituelt baseret autoritet (religiøse specialister) kan vi ikke afgøre fra materialet alene. Statsformation kræver specifikt administrative institutioner vi ikke kan se i arkæologiske fund","accepted_answers":["Bronzens tilstedeværelse i Danmark kræver import (tin fra Cornwall og Centraleuropa, kobber fra Alperne og Sardinien) over tusindvis af kilometer. Kontrol over adgangen til bronze giver social magt — koncentration af bronzegenstande i visse grave indikerer en fremvoksende elite. Men om dette var arvet elite (proto-aristokrati), opnået status (handelshøvdinge) eller rituelt baseret autoritet (religiøse specialister) kan vi ikke afgøre fra materialet alene. Statsformation kræver specifikt administrative institutioner vi ikke kan se i arkæologiske fund"],"review_text":"Timothy Earle og Kristian Kristiansens Bronze Age Transformations (2010) og Earles How Chiefs Come to Power (1997) er grundlæggende. Earle anvender antropologisk chiefly-theory: høvdingedømmer (chiefdoms) er mellemstadier mellem stammesamfund og stater karakteriseret ved redistribution, monumentbyggeri og handelskontrol men uden skriftlig administration. Danmark i ældre bronzealder (1700-1100 f.Kr.) passer analytisk til chiefly model. Lead isotope-analyser af danske bronzegenstande (Northover, 1982; Ixer og Budd) viser præcis geografisk oprindelse for metallerne — de bekræfter de lange handelsnetværk. Egtvedpigenens strontium-isotopsignatur (Frei et al. 2015) viste at hun ikke var dansk men muligvis fra Sydtyskland — direkte bevis for personbevægelse over lange distancer. Det vigtige metodologiske spørgsmål: vi kan se materiel ulighed (store vs. simple grave) men ikke direkte den sociale mekanisme der producerede den. Rituel, militær og handelsmagt er alle kompatible med materialet."}$$::jsonb,
  'mc','short',$${"concepts":["bronzealdershandel","social differentiering","chiefly theory","Earle","Kristiansen","statsformation"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Demokratiserede jernets udbredelse det forhistoriske samfund — og hvad er styrken og svaghederne i dette argument?","options":["Argumentet har substans: jern er langt mere udbredt end tin og kobber (bronze kræver sjældne og geografisk koncentrerede malme). Lokalt tilgængeligt jernmalm (myremalm) betød at smedning ikke krævede adgang til koncentrerede handelsnetværk. Jern-våben og -redskaber blev tilgængelige for bredere lag. Men 'demokratisering' er et fortolkende begreb vi projicerer: vi ved ikke om overgangen faktisk reducerede social ulighed — det arkæologiske materiale fra jernaldergrave viser fortsat markant status-differentiering. Teknologisk tilgængelighed og social lighed er ikke det samme","Jerns udbredelse demokratiserede definitivt det forhistoriske samfund og eliminerede social ulighed i jernalderen","Jern havde ingen sammenhæng med social organisation — metallers udbredelse er irrelevant for forståelse af forhistorisk hierarki","Bronze og jern var socialt ækvivalente og overgangen fra det ene til det andet havde ingen konsekvenser for social differentiering"],"correct":"Argumentet har substans: jern er langt mere udbredt end tin og kobber (bronze kræver sjældne og geografisk koncentrerede malme). Lokalt tilgængeligt jernmalm (myremalm) betød at smedning ikke krævede adgang til koncentrerede handelsnetværk. Jern-våben og -redskaber blev tilgængelige for bredere lag. Men 'demokratisering' er et fortolkende begreb vi projicerer: vi ved ikke om overgangen faktisk reducerede social ulighed — det arkæologiske materiale fra jernaldergrave viser fortsat markant status-differentiering. Teknologisk tilgængelighed og social lighed er ikke det samme","accepted_answers":["Argumentet har substans: jern er langt mere udbredt end tin og kobber (bronze kræver sjældne og geografisk koncentrerede malme). Lokalt tilgængeligt jernmalm (myremalm) betød at smedning ikke krævede adgang til koncentrerede handelsnetværk. Jern-våben og -redskaber blev tilgængelige for bredere lag. Men 'demokratisering' er et fortolkende begreb vi projicerer: vi ved ikke om overgangen faktisk reducerede social ulighed — det arkæologiske materiale fra jernaldergrave viser fortsat markant status-differentiering. Teknologisk tilgængelighed og social lighed er ikke det samme"],"review_text":"Ernst Wurths Eisenzeitliche Siedlungsforschung og Andreas Hedeagers Iron Age Societies (1992) er relevante. Hedeager dokumenterer at jernaldersamfundet i Danmark (500 f.Kr.–500 e.Kr.) var socialt hierarkisk og markant differentieret: store aristokratiske gårde, rigdomsgrave med glasperler og sydeuropæiske importvarer mod enkle gravlæggelser. Det er præcis omvendt af 'demokratiseringstesen'. Myremalm (limonitisk jernmalm der dannes i moser) var faktisk tilgængeligt i store dele af Jylland og Sjælland — jernudvinding krævede ikke elitens kontrol over fjerne handelsveje som bronze. John Collis (The European Iron Age, 1984) behandler overgangen: bronze fortsatte i elitesammenhænge (smykker, prestige) mens jern tog over i hverdagsredskaber og våben. Det analytisk vigtige: teknologisk 'demokratisering' (bredere materiel adgang) behøver ikke producere social ligestilling. Moderne analogi: internet-teknologi er bredt tilgængeligt men har ikke elimineret informations- og magtulighed."}$$::jsonb,
  'mc','short',$${"concepts":["jern","demokratisering","teknologisk tilgængelighed","Hedeager","myremalm","social ulighed"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad fortæller Egtvedpigenens isotopanalyser os — og hvad er grænsen for hvad vi kan konkludere fra denne enkeltcase?","options":["Strontium- og svovlisotopanalyser (Frei et al. 2015) viser at Egtvedpigen sandsynligvis ikke var opvokset i Danmark men i et område der kemisk svarer til Sydtyskland (Schwarzwald-regionen). Hennes uldskørt er lavet af uld fra et område med lignende kemisk signatur. Det er direkte bevis for at enkeltindivider bevægede sig over meget lange distancer i bronzealderen. Men én person fortæller os ikke om migrationsvolumen, om hun var atypisk aristokrat eller typisk for sin tid, eller om bevægelsen var engangs eller systemisk. Enkeltcase-fund kan åbne nye horisonter men ikke etablere generelle mønstre","Egtvedpigens isotopdata beviser at hele Danmarks bronzealdersbefolkning var indvandret fra Sydtyskland","Egtvedpigen var dansk og isotopdata er misfortolket — strontiumdata kan ikke bruges til at lokalisere geografisk oprindelse","Isotopanalyser af enkeltindivider kan aldrig give meningsfulde informationer om forhistorisk mobilitet og migrations-mønstre"],"correct":"Strontium- og svovlisotopanalyser (Frei et al. 2015) viser at Egtvedpigen sandsynligvis ikke var opvokset i Danmark men i et område der kemisk svarer til Sydtyskland (Schwarzwald-regionen). Hennes uldskørt er lavet af uld fra et område med lignende kemisk signatur. Det er direkte bevis for at enkeltindivider bevægede sig over meget lange distancer i bronzealderen. Men én person fortæller os ikke om migrationsvolumen, om hun var atypisk aristokrat eller typisk for sin tid, eller om bevægelsen var engangs eller systemisk. Enkeltcase-fund kan åbne nye horisonter men ikke etablere generelle mønstre","accepted_answers":["Strontium- og svovlisotopanalyser (Frei et al. 2015) viser at Egtvedpigen sandsynligvis ikke var opvokset i Danmark men i et område der kemisk svarer til Sydtyskland (Schwarzwald-regionen). Hennes uldskørt er lavet af uld fra et område med lignende kemisk signatur. Det er direkte bevis for at enkeltindivider bevægede sig over meget lange distancer i bronzealderen. Men én person fortæller os ikke om migrationsvolumen, om hun var atypisk aristokrat eller typisk for sin tid, eller om bevægelsen var engangs eller systemisk. Enkeltcase-fund kan åbne nye horisonter men ikke etablere generelle mønstre"],"review_text":"Karin Margarita Freis og kollegers analyse (Scientific Reports, 2015) er metodologisk elegant: strontium-isotoper i knoglerne afspejler det drikkevand man voksede op med, som afspejler den lokale geologi. Schwarzwald har en specifik geologisk strontium-signatur der matchede Egtvedpigens knogler. Uldanalysen var komplementær. Opfølgningsstudier (Kristiansen et al., Price et al.) har vist at bronzealderskirkegårde i Danmark indeholder signifikante andele ikke-lokale individer — Egtvedpigen er måske ikke unik men et eksempel på bredere aristokratisk udvekslingsnetværk. Metodologisk er dette et skoleeksempel: et revolutionerende fund kræver validering via systematisk sampling (mange individer, mange lokaliteter) før det kan bæres over i generelle konklusioner. Freias fund åbnede hypotesen om bronzealderens eliteægteskaber og diplomatiske udvekslinger — hypotesen er nu understøttet af bredere sampling men var ikke bevist af Egtvedpigen alene."}$$::jsonb,
  'mc','short',$${"concepts":["Egtvedpigen","isotopanalyse","strontium","migration","enkeltcase-begrænsning","Frei"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad viser overgangen fra ligbrænding til jordbegravelse i forhistorisk Danmark om forholdet mellem arkæologisk forandring og ideologisk forandring?","options":["Den analytiske pointe er at arkæologisk forandring og ideologisk forandring ikke er identiske: overgangen fra inhumation (jordbegravelse) til kremation i yngre bronzealder og tilbage til jordbegravelse i jernalderen registreres tydeligt i det arkæologiske materiale. Men vi kan ikke direkte slutte fra skiftende gravpraksis til skiftende forestillinger om sjæl, efterliv eller krop. Multiple kausalforklaringer er mulige: kontakt med andre kulturer, praktiske hensyn (brændstof, gravplads), sygdom og frygt for smitte, social mode. Arkæologisk forandring er kortlæggelig — den bagvedliggende mentale transformation er infereret, ikke direkte observeret","Overgangen fra jordbegravelse til ligbrænding dokumenterer direkte og entydig en ny forestilling om sjælen som frigjort af bålet — dette er videnskabeligt fastslået","Skiftende gravformer i forhistorien er udelukkende drevet af tilfældig mode uden nogen sammenhæng med forestillinger om liv, død og sjæl","Forhistoriske gravpraksisser er for enkle til at sige noget om menneskenes mentale forestillingsverden — de er kun praktiske håndterings-procedurer"],"correct":"Den analytiske pointe er at arkæologisk forandring og ideologisk forandring ikke er identiske: overgangen fra inhumation (jordbegravelse) til kremation i yngre bronzealder og tilbage til jordbegravelse i jernalderen registreres tydeligt i det arkæologiske materiale. Men vi kan ikke direkte slutte fra skiftende gravpraksis til skiftende forestillinger om sjæl, efterliv eller krop. Multiple kausalforklaringer er mulige: kontakt med andre kulturer, praktiske hensyn (brændstof, gravplads), sygdom og frygt for smitte, social mode. Arkæologisk forandring er kortlæggelig — den bagvedliggende mentale transformation er infereret, ikke direkte observeret","accepted_answers":["Den analytiske pointe er at arkæologisk forandring og ideologisk forandring ikke er identiske: overgangen fra inhumation (jordbegravelse) til kremation i yngre bronzealder og tilbage til jordbegravelse i jernalderen registreres tydeligt i det arkæologiske materiale. Men vi kan ikke direkte slutte fra skiftende gravpraksis til skiftende forestillinger om sjæl, efterliv eller krop. Multiple kausalforklaringer er mulige: kontakt med andre kulturer, praktiske hensyn (brændstof, gravplads), sygdom og frygt for smitte, social mode. Arkæologisk forandring er kortlæggelig — den bagvedliggende mentale transformation er infereret, ikke direkte observeret"],"review_text":"Michael Parker Pearson (The Archaeology of Death and Burial, 1999) og Colin Renfrews Archaeology of Mind (med Paul Bahn) adresserer metodologien for kognitive slutninger i arkæologi. I Danmark registreres skiftet fra jordbegravelse (ældre bronzealder, fx egetrætskister som Skrydstrupkvinden og Egtvedpigen) til urnekremation (yngre bronzealder, ca. 1000 f.Kr.) og derefter tilbage til jordbegravelse med jernalderskeletriger. Hvert skift har paralleller i bredere europæisk materiale (Urnemark-kulturen spreder sig over Europa ca. 1200-800 f.Kr.) — det tyder på kulturel kontakt og spredning snarere end rent lokal innovation. Kognitive slutninger fra gravpraksis er mulige men kræver forsigtighed: Egyptens mumifikation reflekterer forestillinger om kroppens nødvendighed for sjælen; Homers Iliade forbinder kremation med sjælens frigørelse. Men vi projicerer disse tekstbaserede systemer på kulturer der efterlod ingen tekster. Det metodologiske krav: skelne eksplicit mellem hvad materialet viser og hvad vi fortolker."}$$::jsonb,
  'mc','short',$${"concepts":["kremation","jordbegravelse","arkæologisk vs ideologisk forandring","Parker Pearson","Urnemark","kognitive slutninger"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

-- ─── BAND 5 · MODERNE RELEVANS OG HISTORIOGRAFI (4 questions) ───────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er Jared Diamonds 'den værste fejltagelse'-tese om landbruget analytisk holdbar — og hvad er dens stærkeste kritik?","options":["Tesen er analytisk kreativ men metodologisk problematisk: Diamond sammenligner nutidige residu-jæger-samlere (som !Kung San i Kalahari eller Hadza i Tanzania) med forhistoriske bønder og slutter til forhistorisk jæger-samler-velfærd. Men nutidige residu-jæger-samlere er marginaliserede i suboptimale habitater efter årtusinders fortrængning — de repræsenterer muligvis ikke forhistoriske jæger-samlere i optimale europæiske habitater. Tesen udfordrer nyttigt fremskridts-narrativer men dens bevismateriale er indirekte og komparativt forenklet","Diamonds tese er videnskabeligt bevist og der er fuldstændig konsensus om at landbruget var en katastrofe for alle aspekter af menneskelig velfærd","Diamonds tese er fuldstændig fejlagtig og alle data bekræfter at landbruget var en entydig forbedring for alle aspekter af menneskelig velfærd","Diamonds tese er irrelevant for forståelse af forhistorisk Danmark da skandinaviske forhistoriske forhold er fuldstændig usammenlignelige med de kontekster Diamond analyserer"],"correct":"Tesen er analytisk kreativ men metodologisk problematisk: Diamond sammenligner nutidige residu-jæger-samlere (som !Kung San i Kalahari eller Hadza i Tanzania) med forhistoriske bønder og slutter til forhistorisk jæger-samler-velfærd. Men nutidige residu-jæger-samlere er marginaliserede i suboptimale habitater efter årtusinders fortrængning — de repræsenterer muligvis ikke forhistoriske jæger-samlere i optimale europæiske habitater. Tesen udfordrer nyttigt fremskridts-narrativer men dens bevismateriale er indirekte og komparativt forenklet","accepted_answers":["Tesen er analytisk kreativ men metodologisk problematisk: Diamond sammenligner nutidige residu-jæger-samlere (som !Kung San i Kalahari eller Hadza i Tanzania) med forhistoriske bønder og slutter til forhistorisk jæger-samler-velfærd. Men nutidige residu-jæger-samlere er marginaliserede i suboptimale habitater efter årtusinders fortrængning — de repræsenterer muligvis ikke forhistoriske jæger-samlere i optimale europæiske habitater. Tesen udfordrer nyttigt fremskridts-narrativer men dens bevismateriale er indirekte og komparativt forenklet"],"review_text":"Diamonds essay The Worst Mistake in the History of the Human Race (Discover Magazine, 1987) er et af de mest citerede populærvidenskabelige tekster om forhistorie. Marshall Sahlins' Stone Age Economics (1972) er dens direkte forgænger: Sahlins observerede at !Kung San arbejdede ca. 15-20 timer om ugen for mad og definerede dem som 'the original affluent society'. Kritikken (Edwin Wilmsen, Land Filled with Flies, 1989) er substantiel: !Kung San er i dag marginaliserede Botswanaborgere i Kalahari-ørkenen — de er ikke et eksempel på ideale forhistoriske jæger-samlere men på folk der er presset ind i suboptimale habitater. Beregningerne for 'fritid' er kontekstspecifikke. Mark Nathan Cohen (Health and the Rise of Civilization, 1989) giver den stærkeste dokumentation for landbrugets negative sundhedseffekter via skeletatlas — men erkender at hans forhistoriske bondepopulationer primært er fra Mellemøsten og ikke Nordeuropa. Diamonds tese er en intellektuel provokation der berettiget anfægter lineær fremskridtsfortælling — men dens empiriske fundament er smalere end det ser ud."}$$::jsonb,
  'mc','short',$${"concepts":["Diamond","Sahlins","jæger-samler velfærd","metodologisk kritik","fremskridtsnarrativ","Cohen"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den historiografiske risiko ved at bruge forhistorisk Danmark til at legitimere en særlig dansk national identitet?","options":["National-identitets narrativer om forhistorisk 'rene' danskere er historiografisk problematiske af tre grunde: (1) aDNA-forskning viser at Danmark har oplevet mindst tre store genetiske udskiftninger i forhistorien — der er ingen ubrudt kontinuitet fra stenaldermennesker; (2) nationale identiteter er moderne konstruktioner som ikke eksisterede i forhistorien — folk i bondestenalderen identificerede sig med lokalsamfund og slægt, ikke med en nationalstat; (3) brugen af forhistorie til national legitimering er et kendetegn ved politisk instrumentalisering af fortiden. Forhistorien tilhører menneskehedens fælles arv, ikke et enkelt nutidigt folk","Forhistorisk Danmark er et bevis på en særlig og ubrudt dansk national kontinuitet der strækker sig direkte fra stenalderen til i dag","National brug af forhistorie er altid ufarlig og pædagogisk berettiget da det øger elevernes interesse for deres fortid","Forhistorisk arkæologi er irrelevant for moderne national identitet og de to felter bør holdes fuldstændig adskilte uden nogen forbindelse"],"correct":"National-identitets narrativer om forhistorisk 'rene' danskere er historiografisk problematiske af tre grunde: (1) aDNA-forskning viser at Danmark har oplevet mindst tre store genetiske udskiftninger i forhistorien — der er ingen ubrudt kontinuitet fra stenaldermennesker; (2) nationale identiteter er moderne konstruktioner som ikke eksisterede i forhistorien — folk i bondestenalderen identificerede sig med lokalsamfund og slægt, ikke med en nationalstat; (3) brugen af forhistorie til national legitimering er et kendetegn ved politisk instrumentalisering af fortiden. Forhistorien tilhører menneskehedens fælles arv, ikke et enkelt nutidigt folk","accepted_answers":["National-identitets narrativer om forhistorisk 'rene' danskere er historiografisk problematiske af tre grunde: (1) aDNA-forskning viser at Danmark har oplevet mindst tre store genetiske udskiftninger i forhistorien — der er ingen ubrudt kontinuitet fra stenaldermennesker; (2) nationale identiteter er moderne konstruktioner som ikke eksisterede i forhistorien — folk i bondestenalderen identificerede sig med lokalsamfund og slægt, ikke med en nationalstat; (3) brugen af forhistorie til national legitimering er et kendetegn ved politisk instrumentalisering af fortiden. Forhistorien tilhører menneskehedens fælles arv, ikke et enkelt nutidigt folk"],"review_text":"David Lowenthal (The Heritage Crusade and the Spoils of History, 1998) og Neil Asher Silberman dokumenterer udstrakt brug af arkæologi til national legitimering. Dansk romantisk nationalisme i 1800-tallet (N.F.S. Grundtvig, C.J. Thomsen og Nationalmuseets grundlæggelse) konstruerede en sammenhængende narrativ fra stenalderens 'urdanskere' til vikingetidens storhed. Thomsens treperiodesystem (sten-, bronze-, jernalder) fra 1819 var ikke blot en videnskabelig klassifikation men indlejret i en national fortælling om dansk civilisatorisk udvikling. David Reichs aDNA-forskning ødelægger den biologiske kontinuitetspåstand: de fleste moderne danskere er genetisk overvejende Yamnaya-pastoralist efterkommere der ankom ca. 2800 f.Kr. — med tilsætning af anatolsk bondegenomer og et lille mesolitisk restsubstrat. Benedict Andersons Imagined Communities (1983) viser at nationer er forestillede fællesskaber konstrueret i moderniteten. At projicere nationale identiteter tilbage i forhistorien er en anakronisme. Det kritisk-analytiske blik på forhistorie-brugen er en del af historisk dannelse."}$$::jsonb,
  'mc','short',$${"concepts":["national identitet","forhistorie-instrumentalisering","aDNA","Lowenthal","Anderson","historiografisk kritik"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad siger forhistorisk Danmarks handelsnetværk — ravvejen, bronzens lange rejse, Egtvedpigens mobilitet — om menneskets basale sociale natur?","options":["Den forhistoriske evidens viser at udvidede netværk, handel over lange distancer og mobilitet på tværs af geografiske barrierer er basale menneskelige kapaciteter der forudgår stater, markeder og skrift med årtusinder. Haralds Dunckers og Richard Wranghams socialevolution-forskning understøtter at kooperation med fremmede (ikke kun slægt) er en evolutionær kapacitet hos Homo sapiens. Globalisering er ikke en moderne opfindelse — det er en skalering af kapaciteter der er dybe i menneskelig natur. Det udfordrer narrativer om forhistorien som isoleret, lokal og stammebaseret","Forhistorisk Danmarks lange handelsnetværk beviser at Homo sapiens biologisk er determineret til global kapitalisme og fri handel","Forhistoriske handelsnetværk var styret af biologisk konkurrence og aggression — kooperation med fremmede er en rent moderne kulturel opfindelse","Ravvejens og bronzehandelens netværk var for begrænsede og tilfældige til at sige noget meningsfuldt om menneskelig social natur"],"correct":"Den forhistoriske evidens viser at udvidede netværk, handel over lange distancer og mobilitet på tværs af geografiske barrierer er basale menneskelige kapaciteter der forudgår stater, markeder og skrift med årtusinder. Haralds Dunckers og Richard Wranghams socialevolution-forskning understøtter at kooperation med fremmede (ikke kun slægt) er en evolutionær kapacitet hos Homo sapiens. Globalisering er ikke en moderne opfindelse — det er en skalering af kapaciteter der er dybe i menneskelig natur. Det udfordrer narrativer om forhistorien som isoleret, lokal og stammebaseret","accepted_answers":["Den forhistoriske evidens viser at udvidede netværk, handel over lange distancer og mobilitet på tværs af geografiske barrierer er basale menneskelige kapaciteter der forudgår stater, markeder og skrift med årtusinder. Haralds Dunckers og Richard Wranghams socialevolution-forskning understøtter at kooperation med fremmede (ikke kun slægt) er en evolutionær kapacitet hos Homo sapiens. Globalisering er ikke en moderne opfindelse — det er en skalering af kapaciteter der er dybe i menneskelig natur. Det udfordrer narrativer om forhistorien som isoleret, lokal og stammebaseret"],"review_text":"Ravvejen (Bernsteinstrasse) er arkæologisk dokumenteret: baltisk og jysk rav er fundet i mykenske grave i Grækenland (1600-1100 f.Kr.), i Tutankhamons grav og i Fund fra hele Mellemeuropa og Middelhavet. Curt Becks kemiske fingeraftryks-analyse af rav viste at det jyske rav med en karakteristisk succinitsyre-signatur var eksporteret over 2.000+ km. Joseph Henrichs The WEIRDest People in the World (2020) og Michael Tomasellos A Natural History of Human Morality (2016) adresserer den evolutionære basis for udvidet kooperation: Homo sapiens er exceptionelt god til at samarbejde med fremmede baseret på abstrakte sociale normer frem for genetisk slægtskab (den mekanisme der forklarer samarbejde hos andre dyr). David Graeber og David Wengrøs The Dawn of Everything (2021) udfordrer narrativet om at forhistoriske mennesker var begrænset til stamme-kooperation: etnografiske og arkæologiske data viser udstrakt kompleksitet og fleksibilitet. Den moderne relevans er direkte: forhistoriens handelsmønstre viser at institutioner som stater og markeder ikke skabte menneskets evne til fjernkooperation — de skalerede og formaliserede en kapacitet der allerede var der."}$$::jsonb,
  'mc','short',$${"concepts":["ravvejen","handelsnetværk","menneskelig natur","kooperation","Graeber","Henrich"],"misconception_type":"temporal_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det bedste argument for at forhistoriske samfund var mere politisk komplekse og fleksible end standardmodellen antager — og hvad er modargumentet?","options":["Graeber og Wengrøs argument (The Dawn of Everything, 2021): arkæologiske og etnografiske data viser forhistoriske samfund der eksperimenterede bevidst med politiske former — sæsonbaserede hierarkier (vinter: autoritær jæger-leder, sommer: egalitær fiskergruppe), bevidst afvisning af agrarbofast liv hos grupper der kendte til det, og store ikke-hierarkiske urbane centre (Taljanky, Cucuteni). Modargumentet: Graeber og Wengrow er kritiseret (Knüsel, Whittle m.fl.) for selektivt at bruge etnografiske analogier og overfortolke tvetydigt arkæologisk materiale. Standardmodellen om progressive stadier (jæger-samler → stamme → høvdingedømme → stat) er en forenkling, men Graeber og Wengrøs alternativ risikerer at oversælge politisk fleksibilitet","Graeber og Wengrøs analyse er videnskabeligt uomtvistelig og standardmodellen er fuldstændig afvist i moderne arkæologi","Standardmodellens stadiemodel er et uomgængeligt faktum og Graeber og Wengrøs kritik er ikke-videnskabelig","Spørgsmålet om forhistorisk politisk kompleksitet er principielt ubesvareligt og alle fortolkninger er lige gyldige"],"correct":"Graeber og Wengrøs argument (The Dawn of Everything, 2021): arkæologiske og etnografiske data viser forhistoriske samfund der eksperimenterede bevidst med politiske former — sæsonbaserede hierarkier (vinter: autoritær jæger-leder, sommer: egalitær fiskergruppe), bevidst afvisning af agrarbofast liv hos grupper der kendte til det, og store ikke-hierarkiske urbane centre (Taljanky, Cucuteni). Modargumentet: Graeber og Wengrow er kritiseret (Knüsel, Whittle m.fl.) for selektivt at bruge etnografiske analogier og overfortolke tvetydigt arkæologisk materiale. Standardmodellen om progressive stadier (jæger-samler → stamme → høvdingedømme → stat) er en forenkling, men Graeber og Wengrøs alternativ risikerer at oversælge politisk fleksibilitet","accepted_answers":["Graeber og Wengrøs argument (The Dawn of Everything, 2021): arkæologiske og etnografiske data viser forhistoriske samfund der eksperimenterede bevidst med politiske former — sæsonbaserede hierarkier (vinter: autoritær jæger-leder, sommer: egalitær fiskergruppe), bevidst afvisning af agrarbofast liv hos grupper der kendte til det, og store ikke-hierarkiske urbane centre (Taljanky, Cucuteni). Modargumentet: Graeber og Wengrow er kritiseret (Knüsel, Whittle m.fl.) for selektivt at bruge etnografiske analogier og overfortolke tvetydigt arkæologisk materiale. Standardmodellen om progressive stadier (jæger-samler → stamme → høvdingedømme → stat) er en forenkling, men Graeber og Wengrøs alternativ risikerer at oversælge politisk fleksibilitet"],"review_text":"David Graeber og David Wengrøs The Dawn of Everything: A New History of Humanity (2021) er den mest indflydelsesrige og kontroversielle forhistoriske syntese i årtiet. Deres centrale tese: Rousseau/Hobbes-debatten om naturliv er begge forkerte og bygger på en forenklet evolutionær stige. Reelle forhistoriske data viser politisk eksperimentering og bevidste valg. Cucuteni-Trypillia-kulturen i Ukraine (ca. 4000-3500 f.Kr.) producerede byer på 10.000-20.000 mennesker uden arkæologisk tegn på centrale magt-hierarkier — intet palads, ingen aristokratiske grave, ingen administrative bygninger. Det er analytisk remarkabelt. Alasdair Whittle (The Times of Their Lives, 2014) og et panel af arkæologer i Cambridge Archaeological Journal (2022) kritiserer Graeber og Wengrow for at ignorere negative evidens og for at over-afhænge af specifikke fund. Den metodologisk modne position: The Dawn of Everything stiller de rigtige spørgsmål og præsenterer genuine modeksempler til stadieteorien. Men dens svar — at forhistoriske mennesker var politisk bevidste valgtagere ligesom moderne borgere — er en fortolkning, ikke et bevist faktum. Begge positioner er produktive netop fordi de er i reel faglig diskussion."}$$::jsonb,
  'mc','short',$${"concepts":["Graeber","Wengrow","stadiemodel","politisk kompleksitet","Cucuteni","forhistorisk demokrati"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"prehistoric_denmark"}$$::jsonb,
  'mc_single',5,'auto',true,'prehistoric_denmark',9,5
);
